  },
  any: { fn: async (r, a, ctx) => { for (const x of r as unknown[]) if (B(await ctx.call(a[0]!, [x]))) return true; return false; } },
  all: { fn: async (r, a, ctx) => { for (const x of r as unknown[]) if (!B(await ctx.call(a[0]!, [x]))) return false; return true; } },
  fold: {
